#!/usr/bin/env bash
# Question 6: CronJob ${Q6_APP} never succeeds. Generated by Quick Create; variables arrive as environment variables.
set -euo pipefail

kubectl create namespace "${Q6_NS}" >/dev/null 2>&1 || kubectl get namespace "${Q6_NS}" >/dev/null
timeout 60 bash -c "until kubectl -n '${Q6_NS}' get serviceaccount default >/dev/null 2>&1; do sleep 1; done"
kubectl apply -f - <<EOF
apiVersion: batch/v1
kind: CronJob
metadata:
  name: ${Q6_APP}
  namespace: ${Q6_NS}
spec:
  schedule: "* * * * *"
  suspend: true
  successfulJobsHistoryLimit: 3
  failedJobsHistoryLimit: 3
  jobTemplate:
    spec:
      backoffLimit: 2
      template:
        spec:
          restartPolicy: Never
          containers:
            - name: report
              image: busybox:1.36
              command: ["sh", "-c", "date; sleep 8; echo report done"]
EOF
kubectl -n "${Q6_NS}" get cronjob "${Q6_APP}" -o jsonpath='{.metadata.uid}' > "/var/tmp/cka-q6.uid"
chmod 644 "/var/tmp/cka-q6.uid"

case "${Q6_FAULT}" in
  suspended) ;;
  deadline)
    kubectl -n "${Q6_NS}" patch cronjob "${Q6_APP}" --type=merge -p '{"spec":{"suspend":false}}'
    kubectl -n "${Q6_NS}" patch cronjob "${Q6_APP}" --type=json -p '[{"op":"add","path":"/spec/jobTemplate/spec/activeDeadlineSeconds","value":3}]'
    ;;
  backoff-zero-command)
    kubectl -n "${Q6_NS}" patch cronjob "${Q6_APP}" --type=merge -p '{"spec":{"suspend":false}}'
    kubectl -n "${Q6_NS}" patch cronjob "${Q6_APP}" --type=json -p '[{"op":"replace","path":"/spec/jobTemplate/spec/backoffLimit","value":0},{"op":"replace","path":"/spec/jobTemplate/spec/template/spec/containers/0/command/2","value":"date; sleep 8; ech report done"}]'
    ;;
  image-registry)
    kubectl -n "${Q6_NS}" patch cronjob "${Q6_APP}" --type=merge -p '{"spec":{"suspend":false}}'
    kubectl -n "${Q6_NS}" patch cronjob "${Q6_APP}" --type=json -p '[{"op":"replace","path":"/spec/jobTemplate/spec/template/spec/containers/0/image","value":"registry.invalid/busybox:1.36"}]'
    ;;
  concurrency-forbid-stuck)
    kubectl -n "${Q6_NS}" patch cronjob "${Q6_APP}" --type=json -p '[{"op":"add","path":"/spec/concurrencyPolicy","value":"Forbid"},{"op":"replace","path":"/spec/jobTemplate/spec/template/spec/containers/0/command/2","value":"date; echo waiting for the upstream export; sleep 100000"}]'
    kubectl -n "${Q6_NS}" patch cronjob "${Q6_APP}" --type=merge -p '{"spec":{"suspend":false}}'
    for _ in $(seq 1 45); do
      [[ -n "$(kubectl -n "${Q6_NS}" get cronjob "${Q6_APP}" -o jsonpath='{.status.active}')" ]] && break
      sleep 2
    done
    [[ -n "$(kubectl -n "${Q6_NS}" get cronjob "${Q6_APP}" -o jsonpath='{.status.active}')" ]] || { echo "the CronJob started no Job" >&2; exit 1; }
    kubectl -n "${Q6_NS}" patch cronjob "${Q6_APP}" --type=json -p '[{"op":"replace","path":"/spec/jobTemplate/spec/template/spec/containers/0/command/2","value":"date; sleep 8; echo report done"}]'
    ;;
  *)
    echo "unknown fault" >&2
    exit 1
    ;;
esac
